import{_ as a,o as i,c as e,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"TCP/IP 内核栈与 NAPI","description":"","frontmatter":{},"headers":[],"relativePath":"os/net/kernel-tcp.md","filePath":"os/net/kernel-tcp.md","lastUpdated":1788475713000}'),p={name:"os/net/kernel-tcp.md"};function l(t,s,h,r,c,o){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="tcp-ip-内核栈与-napi" tabindex="-1">TCP/IP 内核栈与 NAPI <a class="header-anchor" href="#tcp-ip-内核栈与-napi" aria-label="Permalink to &quot;TCP/IP 内核栈与 NAPI&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>Linux 内核的 TCP/IP 协议栈是工程上最被低估的子系统之一：&quot;高了一个量级&quot;。现代内核 + 多队列网卡 + NAPI + io_uring + eBPF 在 100 Gbps 的网络下还能跑出 50% 的线速。这章拆开 TCP/IP 内核栈的 packet lifecycle + NAPI 机制 + RPS/RFS/XPS 软中断分发, 让你看懂 &quot;16 核 100 Gbps NIC 实际能跑多少&quot;。</p><h2 id="_1-一个-packet-的-lifecycle" tabindex="-1">1. 一个 packet 的 lifecycle <a class="header-anchor" href="#_1-一个-packet-的-lifecycle" aria-label="Permalink to &quot;1. 一个 packet 的 lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NIC RX 流 ingress frame</span></span>
<span class="line"><span>   ↓ DMA 到 ring buffer (RX ring)</span></span>
<span class="line"><span>   ↓ 触发 IRQ, 内核 NAPI 软中断</span></span>
<span class="line"><span>   ↓ net_rx_action → E1000 driver → netif_receive_skb</span></span>
<span class="line"><span>   ↓ 进入协议栈:</span></span>
<span class="line"><span>        L2 (eth_type_trans)</span></span>
<span class="line"><span>        L3 (ip_rcv)</span></span>
<span class="line"><span>        L4 (tcp_v4_rcv)</span></span>
<span class="line"><span>   ↓ socket 收包队列</span></span>
<span class="line"><span>   ↓ syscall recvmsg 拷贝到 user</span></span></code></pre></div><p>每 packet 经过 ~20 个函数, 2000-5000 cycles 抵达 user space.</p><p>2000 cycles ÷ 3 GHz = ~ 700 ns / packet ⇒ 1.4 Mpps / core (kernel 网络栈极限).</p><p>50 Gbps 流量 ÷ 1500 MTU = 4 M pps ⇒ <strong>超过单 core 网络处理能力</strong>.</p><p>这就是为什么内核需要 multi-queue NIC + multi-core scaling.</p><h2 id="_2-napi-中断-轮询混合" tabindex="-1">2. NAPI: 中断 + 轮询混合 <a class="header-anchor" href="#_2-napi-中断-轮询混合" aria-label="Permalink to &quot;2. NAPI: 中断 + 轮询混合&quot;">​</a></h2><p>NIC 旧模型: 每 packet 触发 1 IRQ + 内核 IRQ handler 处理. pps 高时 IRQ storm 撕 CPU.</p><p>NAPI (New API):</p><ul><li>第一 packet 触发 IRQ, kernel 知道 NIC 有数据;</li><li>之后关闭 NIC IRQ, kernel 软中断轮询 (net_rx_action) 在该 NIC 上拉 ~64 个 packet 直到 N;</li><li>没数据再 rearm IRQ.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NIC RX IRQ → net_rx_action → poll up to 64 packets → no more → rearm IRQ</span></span></code></pre></div><p>收益: 5 Mpps 流量下从每 N 次切换 IRQ (50 万 IRQ/s) 降到万次 IRQ/s.</p><h2 id="_3-multi-queue-nic-irq-分配" tabindex="-1">3. Multi-queue NIC + IRQ 分配 <a class="header-anchor" href="#_3-multi-queue-nic-irq-分配" aria-label="Permalink to &quot;3. Multi-queue NIC + IRQ 分配&quot;">​</a></h2><p>NIC 256 RX/TX queue (modern Mellanox CX-6/7), 内核把每个 queue 的 IRQ 通过 <code>smp_affinity</code> 拆到 CPU:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/irq/N/smp_affinity_list</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0-3&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/irq/N/smp_affinity</span></span></code></pre></div><p>XPS (Transmit Packet Steering): TX queue 选 CPU 默认; RPS (Receive Packet Steering): RX hash 把 packet 拆到任一 CPU; RFS (Receive Flow Steering): 按 socket 所在 CPU 转, 提高 cache. aRFS: 自动 RFS, NIC 直接 dispatch.</p><p><strong>完美配置</strong>: 每 RX queue 绑一 CPU, IRQ 不跨 socket, RPS 关, aRFS 开.</p><h2 id="_4-网络栈代码路径复杂度" tabindex="-1">4. 网络栈代码路径复杂度 <a class="header-anchor" href="#_4-网络栈代码路径复杂度" aria-label="Permalink to &quot;4. 网络栈代码路径复杂度&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packet rate / CPU:</span></span>
<span class="line"><span>  单核 raw socket (PF_RING zero bypass): ~ 14 Mpps (14 ns/pkt)</span></span>
<span class="line"><span>  单核 gro + tcp + recvmsg: 1.5 Mpps (700 ns/pkt)</span></span>
<span class="line"><span>  单核单 epoll + 1024 是可能 0 ms latency јѕ 5 ms env: ~ 1 Mpps</span></span></code></pre></div><p>高 PPS 越接近 kernel 1750 ns 限 = 需要走 bypass.</p><h2 id="_5-gro-gso-聚合大小-packet-减少-chain" tabindex="-1">5. GRO/GSO: 聚合大小 packet 减少 chain <a class="header-anchor" href="#_5-gro-gso-聚合大小-packet-减少-chain" aria-label="Permalink to &quot;5. GRO/GSO: 聚合大小 packet 减少 chain&quot;">​</a></h2><ul><li>GRO (Generic Receive Offload): NIC 改 packet frame 收大小异常, kernel 内部 merge 多个 small packet 大 64 KB unit 给上层 stack ⇒ stack 跑一次 vs 100 次;</li><li>GSO (Generic Segmentation Offload): 出向, kernel 把 64 KB 巨型 segment 丢给 NIC, NIC 自己分成 MTU-size.</li></ul><p>现代 NIC 通常支持 hardware GRO/GSO, 优势 of tcp burst.</p><h2 id="_6-ebpf-xdp-内核暖些-pre-router" tabindex="-1">6. eBPF + XDP: 内核暖些 pre-router <a class="header-anchor" href="#_6-ebpf-xdp-内核暖些-pre-router" aria-label="Permalink to &quot;6. eBPF + XDP: 内核暖些 pre-router&quot;">​</a></h2><p>eBPF 在网络 packet 收入 frame 阶段可以编程:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NIC RX queue → XDP (eXpress Data Path) hook → 用户 eBPF program →</span></span>
<span class="line"><span>   ↓ 丢 / 重定向 / let go to kernel stack</span></span></code></pre></div><p>XDP eBPF program 通常处理 packet:</p><ul><li>DDoS 现场丢 IP 黑名单;</li><li>L4 load-balancer (e.g. Cilium LB);</li><li>NAT + 防火墙规则;</li><li>metric collection.</li></ul><p>性能: XDP 在 Linux 5.0+ 已经能到 24 Mpps per CPU, 远超传统 kernel stack. 这是 Cilium / cloudflare 等工业核心.</p><h2 id="_7-多语言同一抽象" tabindex="-1">7. 多语言同一抽象 <a class="header-anchor" href="#_7-多语言同一抽象" aria-label="Permalink to &quot;7. 多语言同一抽象&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ef: 内核栈可用 = 不需要直接里程.</span></span>
<span class="line"><span>  - C / Rust: libc syscall on socket</span></span>
<span class="line"><span>  - Go: runtime 自己 epoll over socket fd</span></span>
<span class="line"><span>  - Java: NIO epoll</span></span>
<span class="line"><span>  - Node: libuv</span></span>
<span class="line"><span>  - Python: asyncio / trio</span></span></code></pre></div><p>各语言都默认走 kernel TCP/IP stack, 但想要 kernel-bypass 必须自写:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// DPDK 直接 mmap NIC ring</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Onload / OpenOnload 类似 (SolarFlare) NIC driver SDK</span></span></code></pre></div><h2 id="_8-实测生产线式优化" tabindex="-1">8. 实测生产线式优化 <a class="header-anchor" href="#_8-实测生产线式优化" aria-label="Permalink to &quot;8. 实测生产线式优化&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调 NIC IRQ on NUMA socket</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/irq/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/smp_affinity_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> done</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 关闭 packet processing features</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ethtool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -K</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ethtool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -K</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gso</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 仅 debug baseline</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ringbuffer up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ethtool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8192</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8192</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 推荐 mtu 9000 (jumbo) 在 internal cluster: ipv_set dev eth0 mtu 9000</span></span></code></pre></div><h2 id="_9-这章带走的东西" tabindex="-1">9. 这章带走的东西 <a class="header-anchor" href="#_9-这章带走的东西" aria-label="Permalink to &quot;9. 这章带走的东西&quot;">​</a></h2><ul><li>kernel TCP/IP 在单核 ~ 1.5 Mpps 上界;</li><li>NAPI 改 IRQ storm 软轮询, 现代 NIC 必配;</li><li>multi-queue + IRQ smp_affinity + RFS/RPS 让多个核同时处理 RX;</li><li>GRO/GSO 让单 throughput 拓宽 64 KB 上 vs 1.5K MTU 量级;</li><li>bpf + XDP 在 NIC ingress 阶段执行 user code = 24 Mpps per CPU 现代性能;</li><li>真要 100 Gbps line-rate 跑要用 DPDK/XDP full bypass.</li></ul><p>下一节 → <a href="./xdp-dpdk">XDP、DPDK 与 kernel bypass</a></p>`,41)])])}const u=a(p,[["render",l]]);export{d as __pageData,u as default};
